package io.fireflysoftware.core.insurance.underwriting.core.services.governance.impl;

import io.fireflysoftware.core.insurance.underwriting.core.services.governance.StaffUnderwritingAdmission;
import io.fireflysoftware.core.insurance.underwriting.core.services.quotes.QuoteTenantBindingResolver;
import io.fireflysoftware.core.insurance.underwriting.interfaces.governance.*;
import io.fireflysoftware.core.insurance.underwriting.models.governance.UnderwritingGovernanceRows;
import java.time.*;
import java.util.UUID;
import org.fireflyframework.kernel.audit.AuditActor;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class StaffUnderwritingEffectRulesTest {
    final Instant now=Instant.parse("2026-11-01T12:00:00Z");final UUID tenant=UUID.randomUUID(),submission=UUID.randomUUID(),risk=UUID.randomUUID(),party=UUID.randomUUID(),product=UUID.randomUUID(),referral=UUID.randomUUID(),value=UUID.randomUUID();final String digest="a".repeat(64);
    StaffUnderwritingAdmission.Permit permit(GovernedUnderwritingIntent.Operation op,String subject){var intent=new GovernedUnderwritingIntent(op,UUID.randomUUID(),submission,risk,op==GovernedUnderwritingIntent.Operation.REFERRAL_CREATE?null:referral,op==GovernedUnderwritingIntent.Operation.DECISION_RECORD?1:0,op==GovernedUnderwritingIntent.Operation.REFERRAL_CREATE?null:digest,op==GovernedUnderwritingIntent.Operation.REFERRAL_CREATE?"review":null);var binding=new QuoteTenantBindingResolver.Observation("https://issuer.invalid","opaque:tenant",tenant,UUID.randomUUID(),1,digest,1,0,UUID.randomUUID(),0,now,now.plusSeconds(5),now.plusSeconds(60));return new StaffUnderwritingAdmission.Permit(new StaffUnderwritingAdmission.Request(intent,intent.actionId(),intent.intentDigest(tenant),false),binding,"TERM_PC_PROPERTY",new AuditActor("https://issuer.invalid",subject,"registered-staff","opaque:tenant","canonical-insurer-staff",UUID.nameUUIDFromBytes(subject.getBytes(java.nio.charset.StandardCharsets.UTF_8))),"policy-3",UUID.randomUUID(),UUID.randomUUID(),now,System.nanoTime(),now.plusSeconds(5));}
    UnderwritingGovernanceRows.Source source(UUID selectedTenant,String objectType){return new UnderwritingGovernanceRows.Source(selectedTenant,submission,party,product,risk,party,objectType,"QUOTED","PROPERTY","USD",value,1,new java.math.BigDecimal("100000.00"),"USD",OffsetDateTime.ofInstant(now,ZoneOffset.UTC),OffsetDateTime.ofInstant(now,ZoneOffset.UTC));}
    UnderwritingGovernanceRows.ReferralControl control(long version,String state,String creator,String receipt){return new UnderwritingGovernanceRows.ReferralControl(referral,tenant,submission,party,product,risk,version,state,"TERM_PC_PROPERTY","https://issuer.invalid",creator,"canonical-insurer-staff",UUID.nameUUIDFromBytes(creator.getBytes(java.nio.charset.StandardCharsets.UTF_8)),version==1?"https://issuer.invalid":null,version==1?"authorized-approver":null,version==1?"canonical-insurer-staff":null,version==1?UUID.nameUUIDFromBytes("authorized-approver".getBytes(java.nio.charset.StandardCharsets.UTF_8)):null,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),receipt,version==1?StaffUnderwritingEffectRulesImpl.digest(source(tenant,"PROPERTY")):null,OffsetDateTime.ofInstant(now,ZoneOffset.UTC));}
    @Test void aCurrentPropertySourceIsBoundToTheObservedResourceTenant(){assertDoesNotThrow(()->StaffUnderwritingEffectRulesImpl.source(permit(GovernedUnderwritingIntent.Operation.REFERRAL_CREATE,"maker"),source(tenant,"PROPERTY")));assertThrows(SecurityException.class,()->StaffUnderwritingEffectRulesImpl.source(permit(GovernedUnderwritingIntent.Operation.REFERRAL_CREATE,"maker"),source(UUID.randomUUID(),"PROPERTY")));}
    @Test void anotherObjectKindCannotEnterThePropertyDelegation(){assertThrows(SecurityException.class,()->StaffUnderwritingEffectRulesImpl.source(permit(GovernedUnderwritingIntent.Operation.REFERRAL_CREATE,"maker"),source(tenant,"VEHICLE")));}
    @Test void aReferralCreatorCannotApproveTheirOwnReferral(){var p=permit(GovernedUnderwritingIntent.Operation.REFERRAL_APPROVE,"maker");assertThrows(SecurityException.class,()->StaffUnderwritingEffectRulesImpl.control(p,source(tenant,"PROPERTY"),control(0,"OPEN","maker",digest)));}
    @Test void aDistinctCurrentApproverCanUseOnlyTheOriginalOpenReferralReceipt(){var p=permit(GovernedUnderwritingIntent.Operation.REFERRAL_APPROVE,"checker");assertDoesNotThrow(()->StaffUnderwritingEffectRulesImpl.control(p,source(tenant,"PROPERTY"),control(0,"OPEN","maker",digest)));assertThrows(SecurityException.class,()->StaffUnderwritingEffectRulesImpl.control(p,source(tenant,"PROPERTY"),control(0,"OPEN","maker","b".repeat(64))));}
    @Test void anOpenReferralCannotAuthorizeAnAcceptDecision(){assertThrows(SecurityException.class,()->StaffUnderwritingEffectRulesImpl.control(permit(GovernedUnderwritingIntent.Operation.DECISION_RECORD,"underwriter"),source(tenant,"PROPERTY"),control(0,"OPEN","maker",digest)));}
    @Test void onlyTheExactGovernedApprovalVersionCanAuthorizeTheDecision(){var p=permit(GovernedUnderwritingIntent.Operation.DECISION_RECORD,"underwriter");assertDoesNotThrow(()->StaffUnderwritingEffectRulesImpl.control(p,source(tenant,"PROPERTY"),control(1,"APPROVED","maker",digest)));assertThrows(SecurityException.class,()->StaffUnderwritingEffectRulesImpl.control(p,source(tenant,"PROPERTY"),control(2,"APPROVED","maker",digest)));}
    @Test void aChangedCurrentInsuredValueCannotReuseTheGovernedApproval(){var selected=source(tenant,"PROPERTY");var changed=new UnderwritingGovernanceRows.Source(selected.tenantId(),selected.submissionId(),selected.partyId(),selected.productId(),selected.riskId(),selected.riskPartyId(),selected.objectType(),selected.status(),selected.lineOfBusiness(),selected.currency(),selected.valueId(),selected.lineNumber(),new java.math.BigDecimal("200000.00"),selected.valueCurrency(),selected.riskUpdatedAt(),selected.valueUpdatedAt());assertThrows(SecurityException.class,()->StaffUnderwritingEffectRulesImpl.control(permit(GovernedUnderwritingIntent.Operation.DECISION_RECORD,"underwriter"),changed,control(1,"APPROVED","maker",digest)));}
    @Test void aLegacyApprovedRowWithoutGovernedControlCannotBecomeAuthority(){assertThrows(SecurityException.class,()->StaffUnderwritingEffectRulesImpl.control(permit(GovernedUnderwritingIntent.Operation.DECISION_RECORD,"underwriter"),source(tenant,"PROPERTY"),null));}
}
